import numpy as np, json
from collections import deque

def norm(v):
    v=np.array(v,float); return v/np.linalg.norm(v)

class Mol:
    def __init__(self): self.el=[]; self.xyz=[]; self.bonds=[]
    def add(self,el,xyz): self.el.append(el); self.xyz.append(np.array(xyz,float)); return len(self.el)-1
    def bond(self,i,j): self.bonds.append((i,j))

mol=Mol()
def methyl_at(M,P,store=None):
    f=norm(np.array(M)-mol.xyz[P]); t=np.array([0.,0.,1.])
    if abs(np.dot(f,t))>0.9: t=np.array([0.,1.,0.])
    g=norm(np.cross(f,t)); h=np.cross(f,g)
    out=[('C',np.array(M,float))]
    for phi in (0,2*np.pi/3,4*np.pi/3):
        d=-f/3.+(np.sqrt(8)/3.)*(np.cos(phi)*g+np.sin(phi)*h)
        out.append(('H',np.array(M)+1.09*d))
    if store is None:
        iM=mol.add('C',M); mol.bond(iM,P)
        for e,x in out[1:]: mol.bond(iM, mol.add(e,x))
        return iM
    else:
        store.extend(out); return out

def cp_star(Ga_idx,u_dir,phase=0.0):
    Ga=mol.xyz[Ga_idx]; u=norm(u_dir); O=Ga+1.95*u
    t=np.array([0.,0.,1.])
    if abs(np.dot(u,t))>0.9: t=np.array([1.,0.,0.])
    e1=norm(np.cross(u,t)); e2=np.cross(u,e1)
    ring=[mol.add('C', O+1.20*(np.cos(phase+2*np.pi*i/5)*e1+np.sin(phase+2*np.pi*i/5)*e2)) for i in range(5)]
    mol.bond(Ga_idx,ring[0])
    for i in range(5): mol.bond(ring[i],ring[(i+1)%5])
    for c in ring:
        methyl_at(mol.xyz[c]+1.50*norm(mol.xyz[c]-O), c)
    return ring

Ni=mol.add('Ni',[0,0,0])
Ga1=mol.add('Ga',[-1.84,1.10,0.83]); Ga2=mol.add('Ga',[1.84,1.10,0.83])
Ga3=mol.add('Ga',[-1.48,-1.76,0.0]); Ga4=mol.add('Ga',[1.48,-1.76,0.0])
for g in (Ga1,Ga2,Ga3,Ga4): mol.bond(Ni,g)
cp_star(Ga1, norm(mol.xyz[Ga1]), 0.3)
cp_star(Ga2, norm(mol.xyz[Ga2]), 0.9)
cp_star(Ga3, norm(mol.xyz[Ga3]), 2.2)

N1=mol.add('N',[0.0,-2.70,-0.30]); mol.bond(Ga3,N1); mol.bond(Ga4,N1)
nN=mol.add('N',[3.05,-2.20,0.0]); mol.bond(Ga4,nN)
nC=mol.add('C',[4.25,-2.65,0.0]); mol.bond(nN,nC)
methyl_at([5.30,-3.05,0.0], nC)

dC=norm([0.25,-0.30,-0.92])
Cq=mol.add('C', mol.xyz[N1]+1.47*dC); mol.bond(N1,Cq)
v3=norm(mol.xyz[Ga3]-mol.xyz[N1]); v4=norm(mol.xyz[Ga4]-mol.xyz[N1]); vC=norm(mol.xyz[Cq]-mol.xyz[N1])
hdir=-norm(v3+v4+vC)
hN=mol.add('H', mol.xyz[N1]+1.01*hdir); mol.bond(N1,hN)

axCH2=norm([0.85,-0.45,-0.28]); axCs=norm([-0.75,-0.25,-0.35])
CH2=mol.add('C', mol.xyz[Cq]+1.33*axCH2); mol.bond(Cq,CH2)
nplane=norm(np.cross(axCH2,axCs))
hCH2=[mol.add('H', mol.xyz[CH2]+1.08*norm(axCH2+0.85*s*nplane)) for s in (+1,-1)]
for h in hCH2: mol.bond(CH2,h)
Cs=mol.add('C', mol.xyz[Cq]+1.52*axCs); mol.bond(Cq,Cs)

d3=norm(mol.xyz[Cq]-mol.xyz[Cs])
base=np.array([0.,-0.6,-0.8])
bp=base-np.dot(base,d3)*d3; bp=norm(bp)
def frame(psi,refl):
    w=np.cos(psi)*bp+np.sin(psi)*np.cross(d3,bp)
    pp=np.cos(np.radians(126))*d3+np.sin(np.radians(126))*w
    mm=np.cross(d3,pp)
    if refl: mm=-mm
    return norm(pp),norm(mm)
def sigma_cp_atoms(pp,mm):
    O2=mol.xyz[Cs]+1.19*pp
    pts=[('C',mol.xyz[Cs])]
    for th in (108,252,36,324):
        r=np.radians(th)
        pts.append(('C', O2+1.19*(np.cos(r)*(-pp)+np.sin(r)*mm)))
    ring=[p for e,p in pts]
    for k,c in enumerate(ring):
        if k==0:
            dd1=norm(ring[1]-c); dd2=norm(ring[4]-c); dm=norm(-(dd1+dd2+d3))
        else:
            dm=norm(c-O2)
        f=dm; t=np.array([0.,0.,1.])
        if abs(np.dot(f,t))>0.9: t=np.array([0.,1.,0.])
        g=norm(np.cross(f,t)); hh=np.cross(f,g)
        M=c+1.50*dm
        pts.append(('C',M))
        for phi in (0,2*np.pi/3,4*np.pi/3):
            d=-f/3.+(np.sqrt(8)/3.)*(np.cos(phi)*g+np.sin(phi)*hh)
            pts.append(('H',M+1.09*d))
    return pts

nbase=len(mol.el)
B=np.array(mol.xyz)
best=None
for k in range(36):
    psi=2*np.pi*k/36
    for refl in (False,True):
        pp,mm=frame(psi,refl)
        pts=sigma_cp_atoms(pp,mm)
        A=np.array([p for e,p in pts])
        d=np.linalg.norm(A[:,None,:]-B[None,:,:],axis=-1).min()
        if best is None or d>best[0]: best=(d,k,refl,pp,mm)
print('best min dist', round(best[0],2), 'psi idx', best[1], 'refl', best[2])
pp,mm=best[3],best[4]
pts=sigma_cp_atoms(pp,mm)
# commit with bonds
O2=mol.xyz[Cs]+1.19*pp
ring2=[Cs]+[mol.add('C',p) for e,p in pts[1:5]]
for i in range(5): mol.bond(ring2[i],ring2[(i+1)%5])
idx=5
for k,c in enumerate(ring2):
    iM=mol.add('C',pts[idx][1]); idx+=1
    mol.bond(c,iM)
    for _ in range(3):
        mol.bond(iM, mol.add('H',pts[idx][1])); idx+=1

X=np.array(mol.xyz); n=len(mol.el)
adj={i:set() for i in range(n)}
for i,j in mol.bonds: adj[i].add(j); adj[j].add(i)
topo=np.full((n,n),99,int)
for s in range(n):
    topo[s,s]=0; dq=deque([s])
    while dq:
        u=dq.popleft()
        if topo[s,u]>=4: continue
        for v in adj[u]:
            if topo[s,v]>topo[s,u]+1: topo[s,v]=topo[s,u]+1; dq.append(v)
bad=[]
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(X[i]-X[j]); t=topo[i,j]
        lim=0 if t<=1 else (1.85 if t==2 else (1.9 if t==3 else 1.7))
        if d<lim: bad.append((round(d,2),i,mol.el[i],j,mol.el[j],t))
bad.sort(); print('clashes:',bad[:10]); print('n=',n)
from collections import Counter; print(Counter(mol.el))
with open('init.xyz','w') as f:
    f.write(f"{n}\ninit\n")
    for e,x in zip(mol.el,X): f.write(f"{e} {x[0]:.6f} {x[1]:.6f} {x[2]:.6f}\n")
json.dump({'Ni':Ni,'Ga1':Ga1,'Ga2':Ga2,'Ga3':Ga3,'Ga4':Ga4,'N1':N1,'nN':nN,'nC':nC},open('idx.json','w'))
